pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // 1. Restrict to admissible domain: the caller must be the initial owner.
        address initialOwner = c.owner();
        vm.assume(initialOwner != address(0));
        // fuzzer-supplied newOwner can be any address (including address(0), which is allowed)

        // 2. Drive the transfer as the current owner
        vm.prank(initialOwner);
        c.transferOwnership(newOwner);

        // 3. Assert: owner must equal newOwner. Correct C satisfies this for all inputs;
        //    buggy version will fail whenever newOwner != address(0).
        assertTrue(c.owner() == newOwner);
    }
}

