pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        // setup: set owner to caller so only caller can legitimately change it
        vm.prank(address(0xdead));
        c.transferOwnership(caller);

        vm.prank(caller);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // If the call succeeded, the new owner must be exactly newOwner.
        if (ok) {
            assertEq(c.owner(), newOwner);
        }
    }
}

